(11, 1, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Chào buổi sáng ạ, thưa thầy.', '/uploads/audios/sentences/sensei-ohayou-gozaimasu.mp3', '/uploads/images/vocab/ohayou.png', '{"romaji": "Sensei, ohayou gozaimasu.", "vn": "Chào buổi sáng ạ, thưa thầy.", "jp": "せんせい、おはようございます。", "glossary": {"おはよう": {"r": "ohayou", "v": "chào buổi sáng"}}}'),
(12, 1, 'TRANSLATE_TO_VN', 'Câu 「せんせい、おはようございます。」 có nghĩa là gì?', NULL, NULL, '{"romaji": "Sensei, ohayou gozaimasu.", "jp": "せんせい、おはようございます。", "vn": "Chào buổi sáng ạ, thưa thầy.", "teachAudio": "/uploads/audios/sentences/sensei-ohayou-gozaimasu.mp3", "glossary": {"おはよう": {"r": "ohayou", "v": "chào buổi sáng"}}}'),
(13, 1, 'SPEAKING', 'Nhấn vào micro và đọc to câu sau: せんせい、おはようございます。', '/uploads/audios/sentences/sensei-ohayou-gozaimasu.mp3', '/uploads/images/vocab/ohayou.png', '{"romaji": "Sensei, ohayou gozaimasu.", "vn": "Chào buổi sáng ạ, thưa thầy.", "jp": "せんせい、おはようございます。", "glossary": {"おはよう": {"r": "ohayou", "v": "chào buổi sáng"}}}'),
(14, 1, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Xin chào mọi người.', '/uploads/audios/sentences/minasan-konnichiwa.mp3', '/uploads/images/vocab/konnichiwa.png', '{"romaji": "Minasan, konnichiwa.", "vn": "Xin chào mọi người.", "jp": "みなさん、こんにちは。", "glossary": {"こんにちは": {"r": "konnichiwa", "v": "xin chào (ban ngày)"}}}'),
(15, 1, 'TRANSLATE_TO_VN', 'Câu 「みなさん、こんにちは。」 có nghĩa là gì?', NULL, NULL, '{"romaji": "Minasan, konnichiwa.", "jp": "みなさん、こんにちは。", "vn": "Xin chào mọi người.", "teachAudio": "/uploads/audios/sentences/minasan-konnichiwa.mp3", "glossary": {"こんにちは": {"r": "konnichiwa", "v": "xin chào (ban ngày)"}}}'),
(16, 1, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Chúc ngủ ngon ạ.', '/uploads/audios/sentences/oyasuminasai.mp3', '/uploads/images/vocab/oyasumi.png', '{"romaji": "Oyasuminasai.", "vn": "Chúc ngủ ngon ạ.", "jp": "おやすみなさい。", "glossary": {"おやすみ": {"r": "oyasumi", "v": "chúc ngủ ngon"}}}'),
(17, 1, 'TRANSLATE_TO_VN', 'Câu 「おやすみなさい。」 có nghĩa là gì?', NULL, NULL, '{"romaji": "Oyasuminasai.", "jp": "おやすみなさい。", "vn": "Chúc ngủ ngon ạ.", "teachAudio": "/uploads/audios/sentences/oyasuminasai.mp3", "glossary": {"おやすみ": {"r": "oyasumi", "v": "chúc ngủ ngon"}}}'),
