(1008, 68, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Kính chào quý khách. Quý khách đi mấy người ạ?', '/uploads/audios/sentences/irasshaimase-nanmeisama-desu-ka.mp3', NULL, '{"romaji": "Irasshaimase. Nanmeisama desu ka.", "vn": "Kính chào quý khách. Quý khách đi mấy người ạ?", "jp": "いらっしゃいませ。なんめいさまですか。", "glossary": {"なん": {"r": "nan", "v": "cái gì"}, "いま": {"r": "ima", "v": "bây giờ"}, "まで": {"r": "made", "v": "đến…"}, "で": {"r": "de", "v": "tại (nơi làm gì đó)"}}}'),
(1009, 68, 'TRANSLATE_TO_VN', 'Câu 「いらっしゃいませ。なんめいさまですか。」 có nghĩa là gì?', NULL, NULL, '{"romaji": "Irasshaimase. Nanmeisama desu ka.", "jp": "いらっしゃいませ。なんめいさまですか。", "vn": "Kính chào quý khách. Quý khách đi mấy người ạ?", "teachAudio": "/uploads/audios/sentences/irasshaimase-nanmeisama-desu-ka.mp3", "glossary": {"なん": {"r": "nan", "v": "cái gì"}, "いま": {"r": "ima", "v": "bây giờ"}, "まで": {"r": "made", "v": "đến…"}, "で": {"r": "de", "v": "tại (nơi làm gì đó)"}}}'),
(1010, 68, 'SPEAKING', 'Nhấn vào micro và đọc to câu sau: いらっしゃいませ。なんめいさまですか。', '/uploads/audios/sentences/irasshaimase-nanmeisama-desu-ka.mp3', NULL, '{"romaji": "Irasshaimase. Nanmeisama desu ka.", "vn": "Kính chào quý khách. Quý khách đi mấy người ạ?", "jp": "いらっしゃいませ。なんめいさまですか。", "glossary": {"なん": {"r": "nan", "v": "cái gì"}, "いま": {"r": "ima", "v": "bây giờ"}, "まで": {"r": "made", "v": "đến…"}, "で": {"r": "de", "v": "tại (nơi làm gì đó)"}}}'),
(1011, 68, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Hai người ạ.', '/uploads/audios/sentences/futari-desu.mp3', NULL, '{"romaji": "Futari desu.", "vn": "Hai người ạ.", "jp": "ふたりです。", "glossary": {"ふたり": {"r": "futari", "v": "hai người"}, "で": {"r": "de", "v": "tại (nơi làm gì đó)"}}}'),
(1012, 68, 'TRANSLATE_TO_VN', 'Câu 「ふたりです。」 có nghĩa là gì?', NULL, NULL, '{"romaji": "Futari desu.", "jp": "ふたりです。", "vn": "Hai người ạ.", "teachAudio": "/uploads/audios/sentences/futari-desu.mp3", "glossary": {"ふたり": {"r": "futari", "v": "hai người"}, "で": {"r": "de", "v": "tại (nơi làm gì đó)"}}}'),
(1013, 68, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Xin quý khách đợi một lát ạ.', '/uploads/audios/sentences/shoushou-omachi-kudasai.mp3', NULL, '{"romaji": "Shoushou omachi kudasai.", "vn": "Xin quý khách đợi một lát ạ.", "jp": "しょうしょうおまちください。", "glossary": {"ください": {"r": "kudasai", "v": "cho tôi xin…"}}}'),
