(1407, 97, 'TRANSLATE_TO_VN', 'Câu 「おおきいサイズはありますか。」 có nghĩa là gì?', NULL, NULL, '{"romaji": "Ookii saizu wa arimasu ka.", "jp": "おおきいサイズはありますか。", "vn": "Có cỡ lớn hơn không ạ?", "teachAudio": "/uploads/audios/sentences/ookii-saizu-wa-arimasu-ka.mp3", "glossary": {"あります": {"r": "arimasu", "v": "có (đồ vật)"}, "おおきい": {"r": "ookii", "v": "to, lớn"}, "サイズ": {"r": "saizu", "v": "cỡ, kích thước"}}}'),
(1408, 97, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Tôi thích màu này.', '/uploads/audios/sentences/kono-iro-ga-suki-desu.mp3', '/uploads/images/vocab/iro.png', '{"romaji": "Kono iro ga suki desu.", "vn": "Tôi thích màu này.", "jp": "このいろがすきです。", "glossary": {"の": {"r": "no", "v": "của (nối 2 danh từ)"}, "この": {"r": "kono", "v": "…này"}, "が": {"r": "ga", "v": "trợ từ chủ ngữ"}, "で": {"r": "de", "v": "tại (nơi làm gì đó)"}, "すき": {"r": "suki", "v": "thích"}, "いろ": {"r": "iro", "v": "màu sắc"}}}'),
(1409, 97, 'SPEAKING', 'Nhấn vào micro và đọc to câu sau: スーパーでやさいをかいます。', '/uploads/audios/sentences/suupaa-de-yasai-o-kaimasu.mp3', '/uploads/images/vocab/suupaa.png', '{"romaji": "Suupaa de yasai o kaimasu.", "vn": "Tôi mua rau ở siêu thị.", "jp": "スーパーでやさいをかいます。", "glossary": {"います": {"r": "imasu", "v": "có (người, động vật)"}, "いま": {"r": "ima", "v": "bây giờ"}, "を": {"r": "wo", "v": "trợ từ tân ngữ"}, "で": {"r": "de", "v": "tại (nơi làm gì đó)"}, "かいます": {"r": "kaimasu", "v": "mua"}, "やさい": {"r": "yasai", "v": "rau củ"}, "スーパー": {"r": "suupaa", "v": "siêu thị"}}}'),
(1410, 97, 'SPEAKING', 'Nhấn vào micro và đọc to câu sau: これはいくらですか。', '/uploads/audios/sentences/kore-wa-ikura-desu-ka.mp3', '/uploads/images/vocab/kore.png', '{"romaji": "Kore wa ikura desu ka.", "vn": "Cái này bao nhiêu tiền?", "jp": "これはいくらですか。", "glossary": {"はい": {"r": "hai", "v": "vâng, đúng vậy"}, "いくら": {"r": "ikura", "v": "bao nhiêu tiền"}, "これ": {"r": "kore", "v": "cái này"}, "で": {"r": "de", "v": "tại (nơi làm gì đó)"}}}'),
