(1428, 98, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Hằng ngày tôi đi học bằng xe buýt.', '/uploads/audios/sentences/mainichi-basu-de-gakkou-e-ikimasu.mp3', '/uploads/images/vocab/basu.png', '{"romaji": "Mainichi basu de gakkou e ikimasu.", "vn": "Hằng ngày tôi đi học bằng xe buýt.", "jp": "まいにちバスでがっこうへいきます。", "glossary": {"に": {"r": "ni", "v": "số 2"}, "がっこう": {"r": "gakkou", "v": "trường học"}, "が": {"r": "ga", "v": "trợ từ chủ ngữ"}, "まいにち": {"r": "mainichi", "v": "hằng ngày"}, "いきます": {"r": "ikimasu", "v": "đi"}, "きます": {"r": "kimasu", "v": "đến"}, "へ": {"r": "e", "v": "đến (chỉ hướng)"}, "で": {"r": "de", "v": "tại (nơi làm gì đó)"}, "バス": {"r": "basu", "v": "xe buýt"}}}'),
