(1778, 124, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Đứa bé có đôi mắt to.', '/uploads/audios/sentences/kodomo-wa-me-ga-ookii-desu.mp3', NULL, '{"romaji": "Kodomo wa me ga ookii desu.", "vn": "Đứa bé có đôi mắt to.", "jp": "こどもはめがおおきいです。", "glossary": {"が": {"r": "ga", "v": "trợ từ chủ ngữ"}, "で": {"r": "de", "v": "tại (nơi làm gì đó)"}, "こども": {"r": "kodomo", "v": "trẻ con"}, "おおきい": {"r": "ookii", "v": "to, lớn"}, "め": {"r": "me", "v": "mắt"}}}'),
(1779, 124, 'SPEAKING', 'Nhấn vào micro và đọc to câu sau: きょうはとてもつかれました。', '/uploads/audios/sentences/kyou-wa-totemo-tsukaremashita.mp3', NULL, '{"romaji": "Kyou wa totemo tsukaremashita.", "vn": "Hôm nay tôi rất mệt.", "jp": "きょうはとてもつかれました。", "glossary": {"した": {"r": "shita", "v": "phía dưới"}, "きょう": {"r": "kyou", "v": "hôm nay"}, "とても": {"r": "totemo", "v": "rất"}, "て": {"r": "te", "v": "tay"}}}'),
(1780, 124, 'SPEAKING', 'Nhấn vào micro và đọc to câu sau: あたまがいたいです。', '/uploads/audios/sentences/atama-ga-itai-desu.mp3', '/uploads/images/vocab/atama.png', '{"romaji": "Atama ga itai desu.", "vn": "Tôi bị đau đầu.", "jp": "あたまがいたいです。", "glossary": {"が": {"r": "ga", "v": "trợ từ chủ ngữ"}, "で": {"r": "de", "v": "tại (nơi làm gì đó)"}, "あたま": {"r": "atama", "v": "đầu"}, "いたい": {"r": "itai", "v": "đau"}}}'),
(1781, 124, 'SPEAKING', 'Nhấn vào micro và đọc to câu sau: きょうはうちでやすんでください。', '/uploads/audios/sentences/kyou-wa-uchi-de-yasunde-kudasai.mp3', NULL, '{"romaji": "Kyou wa uchi de yasunde kudasai.", "vn": "Hôm nay hãy nghỉ ở nhà nhé.", "jp": "きょうはうちでやすんでください。", "glossary": {"ください": {"r": "kudasai", "v": "cho tôi xin…"}, "きょう": {"r": "kyou", "v": "hôm nay"}, "で": {"r": "de", "v": "tại (nơi làm gì đó)"}, "うち": {"r": "uchi", "v": "nhà (của mình)"}}}'),
(1782, 124, 'TRANSLATE_TO_VN', 'Câu 「こどもはめがおおきいです。」 có nghĩa là gì?', NULL, NULL, '{"romaji": "Kodomo wa me ga ookii desu.", "jp": "こどもはめがおおきいです。", "vn": "Đứa bé có đôi mắt to.", "teachAudio": "/uploads/audios/sentences/kodomo-wa-me-ga-ookii-desu.mp3", "glossary": {"が": {"r": "ga", "v": "trợ từ chủ ngữ"}, "で": {"r": "de", "v": "tại (nơi làm gì đó)"}, "こども": {"r": "kodomo", "v": "trẻ con"}, "おおきい": {"r": "ookii", "v": "to, lớn"}, "め": {"r": "me", "v": "mắt"}}}'),
(1783, 124, 'TRANSLATE_TO_VN', '「むり」 (muri) nghĩa là gì?', NULL, NULL, '{"kana": "むり", "romaji": "muri", "vn": "quá sức, vô lý", "teachAudio": "/uploads/audios/words/muri.mp3", "glossary": {"むり": {"r": "muri", "v": "quá sức, vô lý"}}}'),
(1784, 124, 'TRANSLATE_TO_VN', 'Câu 「どうしましたか。あたまがいたいです。」 có nghĩa là gì?', NULL, NULL, '{"romaji": "Dou shimashita ka. Atama ga itai desu.", "jp": "どうしましたか。あたまがいたいです。", "vn": "Bạn bị làm sao? Tôi đau đầu.", "teachAudio": "/uploads/audios/sentences/dou-shimashita-ka-atama-ga-itai-desu.mp3", "glossary": {"が": {"r": "ga", "v": "trợ từ chủ ngữ"}, "した": {"r": "shita", "v": "phía dưới"}, "で": {"r": "de", "v": "tại (nơi làm gì đó)"}, "あたま": {"r": "atama", "v": "đầu"}, "いたい": {"r": "itai", "v": "đau"}, "どう": {"r": "dou", "v": "như thế nào"}}}'),
(1785, 124, 'TRANSLATE_TO_VN', '「あたま」 (atama) nghĩa là gì?', NULL, NULL, '{"kana": "あたま", "romaji": "atama", "vn": "đầu", "teachAudio": "/uploads/audios/words/atama.mp3", "glossary": {"あたま": {"r": "atama", "v": "đầu"}}}'),
(1786, 124, 'LISTEN_AND_SELECT', 'Nghe và chọn từ tiếng Nhật đúng', '/uploads/audios/words/yukkuri.mp3', NULL, '{"romaji": "yukkuri", "vn": "từ từ, thong thả", "glossary": {"はな": {"r": "hana", "v": "mũi"}, "て": {"r": "te", "v": "tay"}, "あし": {"r": "ashi", "v": "chân"}, "ゆっくり": {"r": "yukkuri", "v": "từ từ, thong thả"}}}'),
(1787, 124, 'SELECT_IMAGE', 'Chọn hình đúng với từ 「びょうき」 (byouki)', NULL, NULL, '{"kana": "びょうき", "romaji": "byouki", "vn": "bệnh, ốm", "teachAudio": "/uploads/audios/words/byouki.mp3", "glossary": {"びょうき": {"r": "byouki", "v": "bệnh, ốm"}}}'),
(1788, 124, 'LISTEN_AND_ARRANGE', 'Nghe và sắp xếp thành câu hoàn chỉnh: Hôm nay tôi bị sốt.', '/uploads/audios/sentences/kyou-wa-netsu-ga-arimasu.mp3', '/uploads/images/vocab/netsu.png', '{"romaji": "Kyou wa netsu ga arimasu.", "vn": "Hôm nay tôi bị sốt.", "jp": "きょうはねつがあります。", "glossary": {"あります": {"r": "arimasu", "v": "có (đồ vật)"}, "が": {"r": "ga", "v": "trợ từ chủ ngữ"}, "きょう": {"r": "kyou", "v": "hôm nay"}, "ねつ": {"r": "netsu", "v": "sốt"}}}'),
(1789, 124, 'TRANSLATE_TO_VN', '「きぶん」 (kibun) nghĩa là gì?', NULL, NULL, '{"kana": "きぶん", "romaji": "kibun", "vn": "tâm trạng, trong người", "teachAudio": "/uploads/audios/words/kibun.mp3", "glossary": {"きぶん": {"r": "kibun", "v": "tâm trạng, trong người"}}}'),
(1790, 124, 'LISTEN_AND_SELECT', 'Nghe và chọn từ tiếng Nhật đúng', '/uploads/audios/words/netsu.mp3', NULL, '{"romaji": "netsu", "vn": "sốt", "glossary": {"みみ": {"r": "mimi", "v": "tai"}, "あたま": {"r": "atama", "v": "đầu"}, "いたい": {"r": "itai", "v": "đau"}, "ねつ": {"r": "netsu", "v": "sốt"}}}'),
(1791, 124, 'TRANSLATE_TO_VN', '「かい」 (kai) nghĩa là gì?', NULL, NULL, '{"kana": "かい", "romaji": "kai", "vn": "lần (số lần)", "teachAudio": "/uploads/audios/words/kai.mp3", "glossary": {"かい": {"r": "kai", "v": "lần (số lần)"}}}'),
(1792, 124, 'TRANSLATE_TO_JP', '「miệng」 tiếng Nhật nói thế nào?', NULL, '/uploads/images/vocab/kuchi.png', '{"kana": "くち", "romaji": "kuchi", "vn": "miệng", "teachAudio": "/uploads/audios/words/kuchi.mp3", "glossary": {"なか": {"r": "naka", "v": "bên trong"}, "くち": {"r": "kuchi", "v": "miệng"}, "みみ": {"r": "mimi", "v": "tai"}, "あたま": {"r": "atama", "v": "đầu"}, "おなか": {"r": "onaka", "v": "bụng"}}}');
